const p=window.PORTFOLIO;const stack=document.querySelector('#project-stack');stack.innerHTML=p.projects.map((x,i)=>`<article class="project" style="--index:${i};--project-color:var(--${x.theme})"><div class="folder-tab"><span>▟</span> PROJECT 0${i+1}</div><div class="project-body"><div class="project-copy"><span class="mono">0${i+1} / SELECTED WORK</span><h3>${x.title}</h3><p>${x.description}</p><button class="project-link" data-project="${i}">EXPLORE PROJECT</button><div class="project-tags">${x.tags.map(t=>`<span>${t}</span>`).join('')}</div></div><button class="project-art art-${i} selected" data-project="${i}" aria-label="Open ${x.title}"><span class="art-category mono">${x.category}</span><span class="art-number">0${i+1}</span><span class="art-word">${['YOUR<br>WORK.','A NEW<br>POINT<br>OF VIEW.','GOOD<br>THINGS<br>TAKE SHAPE.','MAKE<br>SOME<br>NOISE.'][i]}</span><span class="art-foot mono">PROJECT CANVAS / 0${i+1}</span><i></i><i></i><i></i><i></i></button></div></article>`).join('');
const experiments=[['01 / TYPOGRAPHY','Letter by letter.','TYPE EXPLORATIONS','one','<span class="type-sample">Aa</span>'],['02 / MOTION','A little movement.','MOTION STUDIES','two','<b>✳</b>'],['03 / COLOUR','Happy combinations.','COLOUR & FORM','three','<span class="color-grid">'+ '<i></i>'.repeat(9)+'</span>'],['04 / EXPLORATION','Room for the unexpected.','PERSONAL EXPERIMENTS','four','<span class="play-type">WHAT<br>IF...?</span>']];
document.querySelector('#experiment-grid').innerHTML=experiments.map((x,i)=>`<button class="experiment" data-experiment="${i}"><span class="experiment-tab">${x[0]}</span><span class="experiment-surface experiment-${x[3]}">${x[4]}</span><h3>${x[1]}</h3><p>${x[2]}</p></button>`).join('');
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.querySelector('#hero-name').textContent=p.name;document.title=`${p.name} — Creative Portfolio`;document.querySelector('footer>.mono').innerHTML=`${safe(p.name)} © <span id="year">${new Date().getFullYear()}</span>`;document.querySelectorAll('.avatar').forEach(a=>a.textContent=p.initials);document.querySelectorAll('[data-copy]').forEach(el=>el.textContent=p[el.dataset.copy]);
for(const key of ['portrait','workspace']){if(p[key]){const img=new Image();img.src=p[key];img.alt=key==='portrait'?`${p.name}, portrait`:'My workspace';document.querySelector(`[data-image="${key}"]`).replaceChildren(img);}}
p.projects.forEach((x,i)=>{if(x.cover){const el=document.querySelector(`.art-${i}`);const img=new Image();img.src=x.cover;img.alt=x.title;el.prepend(img);el.classList.add('has-cover');}});
const ruler=document.querySelector('.ruler');for(let n=100;n<=1400;n+=100){const s=document.createElement('span');s.textContent=n;ruler.append(s);}
function updateClock(){document.querySelector('#clock').textContent=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Africa/Lagos'}).format(new Date());}updateClock();setInterval(updateClock,1000);
const reduce=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduce.matches;const toggle=document.querySelector('.motion-toggle');function syncMotion(){document.documentElement.classList.toggle('motion-paused',paused);toggle.textContent=paused?'▷':'Ⅱ';toggle.setAttribute('aria-label',paused?'Resume animations':'Pause animations');toggle.title=paused?'Resume animations':'Pause animations';toggle.setAttribute('aria-pressed',String(paused));}syncMotion();toggle.addEventListener('click',()=>{paused=!paused;syncMotion()});reduce.addEventListener('change',e=>{paused=e.matches;syncMotion()});
if(!reduce.matches)document.body.classList.add('js-motion');const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealObserver.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('.topbar nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'CLOSE':'MENU'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='MENU'}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='MENU'}});
const sectionObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}})},{rootMargin:'-15% 0px -60% 0px'});document.querySelectorAll('main>section[id]').forEach(s=>sectionObserver.observe(s));
const cards=[...document.querySelectorAll('.project')];let queued=false;function updateStack(){queued=false;if(innerWidth<=760)return;cards.forEach((card,i)=>{const next=cards[i+1];card.classList.toggle('is-covered',!!next&&next.getBoundingClientRect().top<innerHeight*.68);});}addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(updateStack)}},{passive:true});updateStack();
const dialog=document.querySelector('#detail-dialog'),dc=document.querySelector('#dialog-content');let returnFocus=null;function show(content){returnFocus=document.activeElement;dc.innerHTML=content;dialog.showModal();document.body.classList.add('dialog-open');document.querySelector('.dialog-close').focus();}function close(){dialog.close();}document.querySelector('.dialog-close').addEventListener('click',close);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});dialog.addEventListener('close',()=>{document.body.classList.remove('dialog-open');returnFocus?.focus()});
function contact(){if(p.email){show(`<span class="mono">LET'S CONNECT</span><h2>Good things start here.</h2><p>Have a project in mind? I'd love to hear about it.</p><a class="dialog-action" href="mailto:${safe(p.email)}">${safe(p.email)}</a>`)}else{show('<span class="mono">CONTACT / COMING SOON</span><h2>Let’s make<br>something good.</h2><p>This space is ready for your email address and social links.</p><div class="contact-placeholder">YOUR CONTACT DETAILS</div>')}}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.hasAttribute('data-contact'))contact();if(t.hasAttribute('data-social')){const key=t.dataset.social;const value=p[key];if(value){if(key==='email')location.href='mailto:'+value;else if(/^https?:\/\//.test(value))window.open(value,'_blank','noopener,noreferrer');}else contact();}if(t.hasAttribute('data-project')){const i=Number(t.dataset.project),x=p.projects[i];show(`<span class="mono">PROJECT 0${i+1} / ${safe(x.category)}</span><h2>${safe(x.title)}</h2><p>${safe(x.description)}</p><div class="detail-meta"><div><span>ROLE</span><b>Your role</b></div><div><span>TIMELINE</span><b>Project duration</b></div><div><span>DELIVERABLE</span><b>${safe(x.category.toLowerCase())}</b></div></div><div class="detail-placeholder">YOUR PROJECT IMAGE OR FILM</div><div class="detail-outline"><section><span class="mono">01 / CONTEXT</span><h3>The challenge</h3><p>Your project’s starting point: who it was for, what needed to change, and why it mattered.</p></section><section><span class="mono">02 / EXPLORATION</span><h3>The process</h3><p>Your research, early ideas, and the decisions that shaped the direction.</p></section><section><span class="mono">03 / EXECUTION</span><h3>The outcome</h3><p>The final experience, the details you cared about, and what you delivered.</p></section><section><span class="mono">04 / REFLECTION</span><h3>What I learned</h3><p>The results, discoveries, and things you would take into your next project.</p></section></div>`)}if(t.hasAttribute('data-experiment')){const x=experiments[Number(t.dataset.experiment)];show(`<span class="mono">PLAYGROUND / ${x[2]}</span><h2>${x[1]}</h2><p>A space for your sketches, motion tests, visual experiments, and things made just for the joy of making.</p><div class="detail-placeholder">YOUR EXPERIMENT GOES HERE</div>`)}if(t.hasAttribute('data-note')){show(`<span class="mono">NOTES / COMING SOON</span><h2>${t.dataset.note==='0'?'A space for your first story.':'The thinking behind the making.'}</h2><p>Your observations, process notes, and stories will live here.</p>`)}});
const cursor=document.querySelector('.custom-cursor'),lens=document.querySelector('.selection-lens');let drag=null;if(matchMedia('(pointer:fine)').matches){document.addEventListener('pointermove',e=>{cursor.style.transform=`translate3d(${e.clientX}px,${e.clientY}px,0)`;cursor.classList.add('active');cursor.classList.toggle('hover',!!e.target.closest('a,button'));if(drag){const w=Math.max(4,Math.abs(e.clientX-drag.x)),h=Math.max(4,Math.abs(e.clientY-drag.y));Object.assign(lens.style,{left:Math.min(e.clientX,drag.x)+'px',top:Math.min(e.clientY,drag.y)+'px',width:w+'px',height:h+'px'});lens.classList.add('active')}});document.addEventListener('pointerdown',e=>{if(e.button!==0||paused||e.target.closest('button,a,dialog,input,textarea'))return;drag={x:e.clientX,y:e.clientY};document.body.style.userSelect='none';});function endDrag(){drag=null;lens.classList.remove('active');document.body.style.userSelect='';}document.addEventListener('pointerup',endDrag);document.addEventListener('pointercancel',endDrag);addEventListener('blur',endDrag);document.addEventListener('pointerleave',()=>{cursor.classList.remove('active');endDrag()});}
